import {previewCourses} from './preview-courses.js';
export const courseOptions=[{id:'bandon',name:'Bandon Dunes',region:'Oregon coast',center:[43.187,-124.391],target:245,media:true},{id:'pinehurst',name:'Pinehurst No. 2',region:'North Carolina',center:[35.190,-79.467],target:250,media:true},{id:'pebble',name:'Pebble Beach Golf Links',region:'California',center:[36.568,-121.950],target:260,media:true},{id:'sawgrass',name:'TPC Sawgrass · Stadium Course',region:'Florida',center:[30.198,-81.394],target:255,media:false}];
export function holeDetails(course,hole){if(!Number.isInteger(hole)||hole<1||hole>18)throw new RangeError('Choose hole 1–18');const n=String(hole).padStart(2,'0'),c=previewCourses.find(c=>c.id===course.id),d=c?.data,t=c?.defaultTee;return {hole,par:c?(d.pars?.[t]||d.holePar)[hole]:null,yards:c?d.yardages[t][hole]:null,tees:c?c.teeNames[t-1]+' tees':'Not configured',photo:course.media&&c?`assets/${course.id}/${c.photoPrefix}-${n}.jpg`:null,video:course.media&&c?`assets/${course.id}/flight-${n}.mp4`:null,art:course.media&&c?`assets/${course.id}/hole-${n}.svg`:null};}

export function groupProgress(id,minutes,scenario){const sampled=scenario==='stale'&&id===8?0:minutes;const progress=Math.min(17.98,Math.max(0,2+(8-id)*.65+sampled/14));return {id,hole:Math.floor(progress)+1,fraction:progress%1,stale:scenario==='stale'&&id===8};}
export function guidance(scenario){return {normal:{title:'A comfortable rhythm.',label:'On pace',text:'Your demo group is keeping appropriate spacing. Enjoy your round.'},queue:{title:'A queue, not a pace problem.',label:'Waiting on traffic',text:'The next tee is busy in this scenario. Waiting does not affect demo reward eligibility.'},gap:{title:'Room to close the gap.',label:'Pace check',text:'A sustained gap has opened in the simulation. Keep pace when safe.'},stale:{title:'An observation, not a live position.',label:'Tracking interrupted',text:'Group 08 is frozen at its last demo observation. No pace warning is issued.'}}[scenario];}
